do $$
declare missing text;
begin
  select string_agg(distinct n, ', ') into missing from (
    select a as n from _wb_games union select b from _wb_games union select team from _wb_scores
  ) x where not exists (select 1 from teams t where lower(t.name) = lower(x.n));
  if missing is not null then raise exception 'No team named: %', missing; end if;
end $$;

insert into schedules (season_id, week_number, home_team_id, away_team_id, is_playoff, is_consolation)
select g.season_id, g.week, least(ta.id, tb.id), greatest(ta.id, tb.id), false, false
from _wb_games g
join teams ta on lower(ta.name) = lower(g.a)
join teams tb on lower(tb.name) = lower(g.b)
where not exists (
  select 1 from schedules s
  where s.season_id = g.season_id and s.week_number = g.week
    and (s.home_team_id in (ta.id, tb.id) or s.away_team_id in (ta.id, tb.id))
);

insert into scores (season_id, week_number, team_id, score)
select w.season_id, w.week, t.id, w.score
from _wb_scores w
join teams t on lower(t.name) = lower(w.team)
on conflict (season_id, week_number, team_id) do nothing;

do $$
declare diff text;
begin
  select string_agg(format('S%s W%s %s: site %s vs workbook %s', w.season_id, w.week, t.name, s.score, w.score), E'\n') into diff
  from _wb_scores w
  join teams t on lower(t.name) = lower(w.team)
  join scores s on s.season_id = w.season_id and s.week_number = w.week and s.team_id = t.id
  where s.score <> w.score;
  raise notice 'Existing scores that differ from the workbook: %', coalesce(E'\n' || diff, 'none');
end $$;

notify pgrst, 'reload schema';
